update card_overrides set data = jsonb_set(jsonb_set(data, '{yes}', coalesce((select jsonb_agg(v) from jsonb_array_elements(coalesce(data->'yes', '[]'::jsonb)) v where v #>> '{}' not in ('rot-swollen-carcass', 'camouflage-frog')), '[]'::jsonb)), '{no}', coalesce((select jsonb_agg(v) from jsonb_array_elements(coalesce(data->'no', '[]'::jsonb)) v where v #>> '{}' not in ('rot-swollen-carcass', 'camouflage-frog')), '[]'::jsonb) || jsonb_build_array('rot-swollen-carcass', 'camouflage-frog')), updated_at = now() where id = '__cfg:map-picks:mu' and deleted = false;
-- drop mosquito-cloud off mw: Bleed: Mosquito Cloud is already on Map 6's list, so it is not lost; Bleed is not meant to be New! on Map 5
-- drop alley-cat off mw: Bleed, Twin Strike: Alley Cat is already on Map 9's list, so it is not lost; Bleed is not meant to be New! on Map 5
-- move swamp-alligator from mw to m8 (source) mw: Bleed: Swamp Alligator carries Bleed; Map 6's table row has it, so it shows there as intended
-- drop cypress-root-lurker off mw: Constrict: Cypress Root Lurker is already on Map 6's list, so it is not lost; Constrict is not meant to be New! on Map 5
-- move marsh-mallow-hare from mw to m21 (source) mw: Cure: Marsh-mallow Hare carries Cure; Map 21's table row has it, so it shows there as intended
-- move newt-doctor from mw to m21 (source) mw: Herbalist: Newt Doctor carries Herbalist; Map 21's table row has it, so it shows there as intended
update card_overrides set data = jsonb_set(jsonb_set(data, '{yes}', coalesce((select jsonb_agg(v) from jsonb_array_elements(coalesce(data->'yes', '[]'::jsonb)) v where v #>> '{}' not in ('mosquito-cloud', 'alley-cat', 'swamp-alligator', 'cypress-root-lurker', 'marsh-mallow-hare', 'newt-doctor')), '[]'::jsonb)), '{no}', coalesce((select jsonb_agg(v) from jsonb_array_elements(coalesce(data->'no', '[]'::jsonb)) v where v #>> '{}' not in ('mosquito-cloud', 'alley-cat', 'swamp-alligator', 'cypress-root-lurker', 'marsh-mallow-hare', 'newt-doctor')), '[]'::jsonb) || jsonb_build_array('mosquito-cloud', 'alley-cat', 'swamp-alligator', 'cypress-root-lurker', 'marsh-mallow-hare', 'newt-doctor')), updated_at = now() where id = '__cfg:map-picks:mw' and deleted = false;
COMMIT;

-- read back
select id, jsonb_array_length(data->'yes') as yes_n, jsonb_array_length(data->'no') as no_n, updated_at from card_overrides where id like '\_\_cfg:map-picks:%' and deleted = false order by id;
